css:
/* From Uiverse.io by Galahhad - Tags: form */
.__UIV_SCOPE__ .content i {
  margin-bottom: 41px;
}

.__UIV_SCOPE__ .container {
  border-radius: 1px;
  padding: 50px 40px 20px 40px;
  box-sizing: border-box;
  font-family: sans-serif;
  color: #737373;
  border: 1px solid rgb(219, 219, 219);
  text-align: center;
  background: white;
}

.__UIV_SCOPE__ .container svg {
  width: 16px;
  height: auto;
}

.__UIV_SCOPE__ .content__form {
  display: flex;
  flex-direction: column;
  row-gap: 14px;
}

.__UIV_SCOPE__ .content__inputs {
  display: flex;
  flex-direction: column;
  row-gap: 8px;
}

.__UIV_SCOPE__ .content__form label {
  border: 1px solid rgb(219, 219, 219);
  display: flex;
  align-items: center;
  position: relative;
  min-width: 268px;
  height: 38px;
  background: rgb(250, 250, 250);
  border-radius: 3px;
}

.__UIV_SCOPE__ .content__form span {
  position: absolute;
  text-overflow: ellipsis;
  transform-origin: left;
  font-size: 12px;
  left: 8px;
  pointer-events: none;
  transition: transform ease-out .1s
}

.__UIV_SCOPE__ .content__form input {
  width: 100%;
  background: inherit;
  border: 0;
  outline: none;
  padding: 9px 8px 7px 8px;
  text-overflow: ellipsis;
  font-size: 16px;
  vertical-align: middle;
}

.__UIV_SCOPE__ .content__form input:valid+span {
  transform: scale(calc(10 / 12)) translateY(-10px);
}

.__UIV_SCOPE__ .content__form input:valid {
  padding: 14px 0 2px 8px;
  font-size: 12px;
}

.__UIV_SCOPE__ .content__or-text {
  display: flex;
  justify-content: space-between;
  align-items: center;
  text-transform: uppercase;
  font-size: 13px;
  column-gap: 18px;
  margin-top: 18px;
}

.__UIV_SCOPE__ .content__or-text span:nth-child(3),
.__UIV_SCOPE__ .content__or-text span:nth-child(1) {
  display: block;
  width: 100%;
  height: 1px;
  background-color: rgb(219, 219, 219);
}

.__UIV_SCOPE__ .content__forgot-buttons {
  display: flex;
  flex-direction: column;
  margin-top: 28px;
  row-gap: 21px;
}

.__UIV_SCOPE__ .content__forgot-buttons button {
  display: flex;
  justify-content: center;
  align-items: center;
  column-gap: 8px;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 12px;
  color: #00376b;
}

.__UIV_SCOPE__ .content__forgot-buttons button:first-child {
  color: #385185;
  font-size: 14px;
  font-weight: 600;
}

.__UIV_SCOPE__ .content__form button {
  background: rgb(0, 149, 246);
  color: white;
  border: none;
  border-radius: 8px;
  font-weight: 700;
  font-size: 14px;
  padding: 7px 16px;
  cursor: pointer;
}

.__UIV_SCOPE__ .content__form button:hover {
  background: rgb(24, 119, 242);
}

.__UIV_SCOPE__ .content__form button:active:not(:hover) {
  background: rgb(0, 149, 246);
  opacity: .7;
}
